:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --text: #e0e0e0;
  --accent: #e94560;
  --accent-hover: #ff6b81;
  --accent-pressed: #c23152;
  --border: #0f3460;
  --focus: #64ffda;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
}

.card {
  background: var(--card-bg);
  border-radius: 16px;
  padding: 32px 24px;
  width: 100%;
  max-width: 720px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  text-align: center;
}

h1 {
  font-size: 1.75rem;
  margin-bottom: 8px;
  letter-spacing: 0.5px;
}

.subtitle {
  font-size: 1rem;
  color: #9aa5b1;
  margin-bottom: 28px;
}

.palette {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
  margin-bottom: 32px;
}

.swatch {
  flex: 1 1 100px;
  min-width: 100px;
  max-width: 140px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
}

.color-box {
  width: 100%;
  height: 120px;
  border-radius: 12px;
  border: 2px solid rgba(255, 255, 255, 0.1);
  transition: transform 0.15s ease, border-color 0.15s ease;
}

.swatch:hover .color-box {
  transform: scale(1.04);
  border-color: rgba(255, 255, 255, 0.35);
}

.hex-label {
  font-size: 0.9rem;
  font-family: 'Courier New', monospace;
  letter-spacing: 1px;
  color: var(--text);
  background: rgba(0, 0, 0, 0.3);
  padding: 4px 8px;
  border-radius: 6px;
  width: 100%;
  text-align: center;
}

.lock-btn {
  font-size: 1.1rem;
  background: transparent;
  border: 2px solid var(--border);
  border-radius: 8px;
  padding: 6px 12px;
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease, transform 0.1s ease;
  line-height: 1;
  color: var(--text);
}

.lock-btn:hover {
  background: rgba(255, 255, 255, 0.08);
  border-color: #4a6fa5;
}

.lock-btn:active {
  transform: scale(0.95);
  background: rgba(255, 255, 255, 0.15);
}

.lock-btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.lock-btn.locked {
  border-color: var(--accent);
  background: rgba(233, 69, 96, 0.2);
}

.generate-btn {
  font-size: 1.1rem;
  font-weight: 600;
  font-family: inherit;
  padding: 14px 32px;
  border: none;
  border-radius: 12px;
  background: var(--accent);
  color: #fff;
  cursor: pointer;
  transition: background 0.15s ease, transform 0.1s ease, box-shadow 0.15s ease;
  width: 100%;
  max-width: 320px;
}

.generate-btn:hover {
  background: var(--accent-hover);
  box-shadow: 0 4px 16px rgba(233, 69, 96, 0.4);
}

.generate-btn:active {
  background: var(--accent-pressed);
  transform: scale(0.97);
}

.generate-btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

@media (max-width: 480px) {
  .card {
    padding: 24px 16px;
  }
  .palette {
    gap: 8px;
  }
  .swatch {
    flex: 1 1 60px;
    min-width: 60px;
  }
  .color-box {
    height: 90px;
  }
  .hex-label {
    font-size: 0.75rem;
    padding: 3px 4px;
  }
  .lock-btn {
    font-size: 0.9rem;
    padding: 4px 8px;
  }
}

(function () {
  'use strict';

  var paletteEl = document.getElementById('palette');
  var generateBtn = document.getElementById('generate');
  var swatches = [];

  function hslToHex(h, s, l) {
    s /= 100;
    l /= 100;
    var a = s * Math.min(l, 1 - l);
    var f = function (n) {
      var k = (n + h / 30) % 12;
      var color = l - a * Math.max(Math.min(k - 3, 9 - k, 1), -1);
      return Math.round(255 * color).toString(16).padStart(2, '0');
    };
    return '#' + f(0) + f(8) + f(4);
  }

  function generateHarmoniousPalette() {
    var baseHue = Math.floor(Math.random() * 360);
    var scheme = Math.floor(Math.random() * 3);
    var hues = [];

    if (scheme === 0) {
      // Analogous
      hues = [baseHue, (baseHue + 30) % 360, (baseHue + 60) % 360, (baseHue + 90) % 360, (baseHue + 120) % 360];
    } else if (scheme === 1) {
      // Complementary-ish
      hues = [baseHue, (baseHue + 180) % 360, (baseHue + 30) % 360, (baseHue + 210) % 360, (baseHue + 60) % 360];
    } else {
      // Triadic-ish
      hues = [baseHue, (baseHue + 120) % 360, (baseHue + 240) % 360, (baseHue + 60) % 360, (baseHue + 180) % 360];
    }

    return hues.map(function (h) {
      var s = 55 + Math.floor(Math.random() * 30);
      var l = 45 + Math.floor(Math.random() * 20);
      return hslToHex(h, s, l);
    });
  }

  function renderPalette(colors) {
    paletteEl.innerHTML = '';
    swatches = [];

    colors.forEach(function (hex, i) {
      var swatch = document.createElement('div');
      swatch.className = 'swatch';
      swatch.setAttribute('role', 'listitem');

      var box = document.createElement('div');
      box.className = 'color-box';
      box.style.backgroundColor = hex;

      var hexLabel = document.createElement('div');
      hexLabel.className = 'hex-label';
      hexLabel.textContent = hex.toUpperCase();

      var lockBtn = document.createElement('button');
      lockBtn.type = 'button';
      lockBtn.className = 'lock-btn';
      lockBtn.textContent = '\uD83D\uDD13';
      lockBtn.setAttribute('aria-label', 'Lock color ' + hex.toUpperCase());
      lockBtn.setAttribute('aria-pressed', 'false');
      lockBtn.dataset.locked = 'false';
      lockBtn.dataset.hex = hex;

      lockBtn.addEventListener('click', function () {
        var locked = lockBtn.dataset.locked === 'true';
        lockBtn.dataset.locked = locked ? 'false' : 'true';
        lockBtn.setAttribute('aria-pressed', locked ? 'false' : 'true');
        lockBtn.classList.toggle('locked', !locked);
        lockBtn.textContent = locked ? '\uD83D\uDD13' : '\uD83D\uDD12';
        lockBtn.setAttribute('aria-label', (locked ? 'Lock' : 'Unlock') + ' color ' + hex.toUpperCase());
      });

      swatch.appendChild(box);
      swatch.appendChild(hexLabel);
      swatch.appendChild(lockBtn);
      paletteEl.appendChild(swatch);

      swatches.push({ hex: hex, locked: false, lockBtn: lockBtn, box: box, hexLabel: hexLabel });
    });
  }

  function updateSwatch(index, hex) {
    var s = swatches[index];
    s.hex = hex;
    s.box.style.backgroundColor = hex;
    s.hexLabel.textContent = hex.toUpperCase();
    s.lockBtn.dataset.hex = hex;
    s.lockBtn.setAttribute('aria-label', (s.lockBtn.dataset.locked === 'true' ? 'Unlock' : 'Lock') + ' color ' + hex.toUpperCase());
  }

  function generate() {
    var newColors = generateHarmoniousPalette();
    swatches.forEach(function (s, i) {
      if (s.lockBtn.dataset.locked !== 'true') {
        updateSwatch(i, newColors[i]);
      }
    });
  }

  generateBtn.addEventListener('click', generate);

  // Initial palette
  renderPalette(generateHarmoniousPalette());
})();
